-- Restrict learner-owned progress RPCs to learner accounts.
CREATE OR REPLACE FUNCTION lms.start_module_atomic(actor_id UUID, target_module_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  target_module lms.modules%ROWTYPE;
  progress_row lms.learner_progress%ROWTYPE;
  now_ts TIMESTAMPTZ := NOW();
BEGIN
  actor := lms.assert_rpc_actor(actor_id);
  IF actor.role <> 'learner' THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501'; END IF;
  SELECT * INTO target_module FROM lms.modules
  WHERE id = target_module_id AND deleted_at IS NULL AND is_published = TRUE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MODULE_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO progress_row FROM lms.learner_progress
  WHERE learner_id = actor.id AND module_id = target_module_id FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO lms.learner_progress(learner_id, module_id, status, started_at)
    VALUES (actor.id, target_module_id, 'in_progress', now_ts) RETURNING * INTO progress_row;
  ELSIF progress_row.status = 'not_started' THEN
    UPDATE lms.learner_progress SET status='in_progress', started_at=COALESCE(started_at,now_ts), completed_at=NULL, updated_at=now_ts
    WHERE id=progress_row.id RETURNING * INTO progress_row;
  END IF;
  RETURN jsonb_build_object('learnerProgressId',progress_row.id,'moduleId',target_module_id,'status',progress_row.status);
END;
$$;

CREATE OR REPLACE FUNCTION lms.save_reflection_atomic(actor_id UUID, target_module_id UUID, reflection_notes TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  target_module lms.modules%ROWTYPE;
  progress_row lms.learner_progress%ROWTYPE;
  now_ts TIMESTAMPTZ := NOW();
BEGIN
  actor := lms.assert_rpc_actor(actor_id);
  IF actor.role <> 'learner' THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501'; END IF;
  SELECT * INTO target_module FROM lms.modules
  WHERE id=target_module_id AND deleted_at IS NULL AND is_published=TRUE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MODULE_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  INSERT INTO lms.learner_progress(learner_id,module_id,status,notes)
  VALUES(actor.id,target_module_id,'not_started',reflection_notes)
  ON CONFLICT(learner_id,module_id) DO UPDATE SET notes=EXCLUDED.notes, updated_at=now_ts
  RETURNING * INTO progress_row;
  RETURN jsonb_build_object('learnerProgressId',progress_row.id,'moduleId',target_module_id,'status',progress_row.status);
END;
$$;

REVOKE ALL ON FUNCTION lms.start_module_atomic(UUID, UUID) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION lms.save_reflection_atomic(UUID, UUID, TEXT) FROM PUBLIC, anon;
